bool StructTraits<::crosapi::mojom::SearchResult::DataView, ::crosapi::mojom::SearchResultPtr>::Read(
    ::crosapi::mojom::SearchResult::DataView input,
    ::crosapi::mojom::SearchResultPtr* output) {
  bool success = true;
  ::crosapi::mojom::SearchResultPtr result(::crosapi::mojom::SearchResult::New());
  
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success)
        result->relevance = input.relevance();
      if (success && !input.ReadDestinationUrl(&result->destination_url))
        success = false;
      if (success && !input.ReadIsOmniboxSearch(&result->is_omnibox_search))
        success = false;
      if (success && !input.ReadIsAnswer(&result->is_answer))
        success = false;
      if (success && !input.ReadOmniboxType(&result->omnibox_type))
        success = false;
      if (success && !input.ReadAnswerType(&result->answer_type))
        success = false;
      if (success && !input.ReadImageUrl(&result->image_url))
        success = false;
      if (success && !input.ReadFavicon(&result->favicon))
        success = false;
      if (success && !input.ReadContents(&result->contents))
        success = false;
      if (success && !input.ReadAdditionalContents(&result->additional_contents))
        success = false;
      if (success && !input.ReadDescription(&result->description))
        success = false;
      if (success && !input.ReadAdditionalDescription(&result->additional_description))
        success = false;
      if (success && !input.ReadAdditionalDescriptionType(&result->additional_description_type))
        success = false;
      if (success && !input.ReadStrippedDestinationUrl(&result->stripped_destination_url))
        success = false;
      if (success && !input.ReadPageTransition(&result->page_transition))
        success = false;
      if (success && !input.ReadContentsType(&result->contents_type))
        success = false;
      if (success && !input.ReadAdditionalContentsType(&result->additional_contents_type))
        success = false;
      if (success && !input.ReadDescriptionType(&result->description_type))
        success = false;
      if (success && !input.ReadDescriptionA11yLabel(&result->description_a11y_label))
        success = false;
      if (success && !input.ReadMetricsType(&result->metrics_type))
        success = false;
      if (success) {
        result->receiver =
            input.TakeReceiver<decltype(result->receiver)>();
      }
  *output = std::move(result);
  return success;
}

