void SearchControllerAsyncWaiter::Search(
    const ::std::u16string& query, ::mojo::PendingAssociatedReceiver<SearchResultsPublisher>* out_publisher) {
  base::RunLoop loop;
  proxy_->Search(std::move(query),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingAssociatedReceiver<SearchResultsPublisher>* out_publisher
,
             ::mojo::PendingAssociatedReceiver<SearchResultsPublisher> publisher) {*out_publisher = std::move(publisher);
            loop->Quit();
          },
          &loop,
          out_publisher));
  loop.Run();
}

